/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
int hobp_rx(UInt32 timeout)
{
  Hobp_Bus_Rx_Q_Msg * q_msg ;

  q_msg = (Hobp_Bus_Rx_Q_Msg *) q_remove (hobp_vars.rx_q_pending ,timeout);
  
  if(q_msg)
    {
      int data = q_msg->data ;

      q_return ((Q_Msg *) q_msg); 

      return data ;
    } 
  
  return HOBP_BUS_TIMEOUT ;

}
//--------------------------------------------------------------------------//
Boolean hobp_rx_data(UInt8 * data , UInt8 size)
{
  UInt8 n ;

  for (n = 0 ; n < size ; n++)
    {
      SInt16 rx_data = hobp_rx(HOBP_RX_BYTE_TIMEOUT) ;

      if(rx_data & 0xFF00)
        {
          return FALSE ;
        }
      
      data[n] = (UInt8)rx_data ;

    }

//  #if DBG_HOBP == 1
//    hobp_dbg_print("" , data , size)        ; 
//  #endif         

  return TRUE ;

}


